*/
FUNCTION GET_DECLARACOES_EM_FALTA(PIN_CDUNIECO IN INTEGER
                        , PIN_CDRAMO IN INTEGER
                        , PIN_NMPOLIZA IN INTEGER) RETURN VARCHAR2;
