FUNCTION FUN_PREM_COM_ME_isento(PI_CDUNIECO IN NUMBER
                             ,PI_NMRECIBO IN NUMBER) RETURN NUMBER AS
aux_ptimport NUMBER;
aux_count    number;
vRAMO		number;
vTABELA		number;
BEGIN
	SELECT NVL(rec.cdramo, crec.cdramo) ramo
		,(
			SELECT decode(cdtipram, 1, 1, 3, 1, 2)
			FROM tramos
			WHERE cdramo = NVL(rec.cdramo, crec.cdramo)
			) tabela
	INTO vRAMO
		,vTABELA
	FROM (
		SELECT cdramo
		FROM mrecibo
		WHERE nmrecibo = PI_NMRECIBO
			AND cdunieco = PI_CDUNIECO
		) rec
	FULL OUTER JOIN (
		SELECT cdramo
		FROM co_dit_mrecibo
		WHERE nmrecibo = PI_NMRECIBO
			AND cdunieco = PI_CDUNIECO
		) crec ON rec.cdramo = crec.cdramo;



	IF vTABELA = 2 THEN
		SELECT SUM(PTIMPORT)
		INTO aux_ptimport
		FROM trecselo r
		WHERE 1 = 1
			AND r.CDTIPCON = (
				SELECT CODIGO
				FROM TMANTENI
				WHERE 1 = 1
					AND CDTABLA = 'TLMIPREM'
					AND CODIGO = CDTIPCON
				)
			AND r.TAXAIMP = 0
			AND r.cdunieco = PI_CDUNIECO
			AND r.nmrecibo = PI_NMRECIBO;

	ELSE
		SELECT SUM(PTIMPORT)
		INTO aux_ptimport
		FROM trecselo
		WHERE 1 = 1
			AND CDTIPCON = (
				SELECT CODIGO
				FROM TMANTENI
				WHERE 1 = 1
					AND CDTABLA = 'TLMIPREM'
					AND CODIGO = CDTIPCON
					and INSTRC(CODIGO,'ME',1,1) > 0
				)
			AND TAXAIMP = 0
			AND NMRECIBO = PI_NMRECIBO
			AND CDUNIECO = PI_CDUNIECO;
	END IF;

  RETURN NVL(AUX_PTIMPORT,0);
END;

