						, p_fecha2  IN DATE
						, p_ind_tippla IN VARCHAR2
						, P_DOMINA IN VARCHAR2 DEFAULT 'S') RETURN NUMBER AS
  V_MONCRE NUMBER (17,5);
  V_REACRE NUMBER(17,5);
  V_MONCAU NUMBER(17,5);
