  V_ERROR  NUMBER;
BEGIN

PL_PLAFOND_GRUPO(P_CDPERSON,p_fecha1,p_fecha2,P_IND_TIPPLA,P_DOMINA,V_MONCRE,V_REACRE,V_MONCAU,V_REACAU,

V_ERROR);
